<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver\Rest\ThemeVersionAllowController;
use Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver\Rest\ThemeVersionListController;
use Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver\Rest\ThemeVersionCreateController;
use Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver\Rest\ThemeVersionRetrieveController;
use Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver\Rest\ThemeVersionUpdateController;
use Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driver\Rest\ThemeVersionDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Service\Visibility\ThemeVersionRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\Create\ThemeVersionCreateAllowDecision;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\Update\ThemeVersionUpdateAllowDecision;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\Retrieve\ThemeVersionRetrieveAllowDecision;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\List\ThemeVersionListAllowDecision;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Document\ThemeVersion\Application\Usecase\Delete\ThemeVersionDeleteAllowDecision;
use Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driven\ThemeVersionReadRepositoryAdapter;
use Civi\Lughauth\Features\Document\ThemeVersion\Infrastructure\Driven\ThemeVersionWriteRepositoryAdapter;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionReadGateway;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\Gateway\ThemeVersionWriteGateway;

class ThemeVersionPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[ThemeVersionReadGateway::class] = \DI\autowire(ThemeVersionReadRepositoryAdapter::class);
        $def[ThemeVersionWriteGateway::class] = \DI\autowire(ThemeVersionWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/theme-versions', [$this, 'setRoutesForThemeVersion']);
        $collector->group('/api/me/acl/document/theme-versions', [$this, 'setRoutesForThemeVersionAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(ThemeVersionRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(ThemeVersionCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(ThemeVersionUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(ThemeVersionRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(ThemeVersionListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(ThemeVersionDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("theme-version", "list", "READ");
            $handler->registerResourceAction("theme-version", "create", "WRITE");
            $handler->registerResourceAction("theme-version", "retrieve", "READ");
            $handler->registerResourceAction("theme-version", "update", "WRITE");
            $handler->registerResourceAction("theme-version", "delete", "WRITE");

            $handler->registerResourceAttribute("theme-version", "theme", "MANAGE");
            $handler->registerResourceAttribute("theme-version", "channel", "MANAGE");
            $handler->registerResourceAttribute("theme-version", "locale", "MANAGE");
            $handler->registerResourceAttribute("theme-version", "contentHtml", "MANAGE");
            $handler->registerResourceAttribute("theme-version", "contentText", "MANAGE");
            $handler->registerResourceAttribute("theme-version", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForThemeVersionAcl(RouteCollectorProxy $themeVersionGroup): void
    {
        $themeVersionGroup->get('', [ThemeVersionAllowController::class, 'genericAllow']);
        $themeVersionGroup->get('/{uid}', [ThemeVersionAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForThemeVersion(RouteCollectorProxy $themeVersionGroup): void
    {
        $themeVersionGroup->get('', [ThemeVersionListController::class, 'list']);
        $themeVersionGroup->post('', [ThemeVersionCreateController::class, 'create']);
        $themeVersionGroup->get('/{uid}', [ThemeVersionRetrieveController::class, 'retrieve']);
        $themeVersionGroup->put('/{uid}', [ThemeVersionUpdateController::class, 'update']);
        $themeVersionGroup->delete('/{uid}', [ThemeVersionDeleteController::class, 'delete']);
        $themeVersionGroup->delete('', [ThemeVersionDeleteController::class, 'deleteAllForQuery']);
        $themeVersionGroup->get('/~/delete-status/{uid}', [ThemeVersionDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
